// Phan tich payload webhook ClickUp. Da xac nhan qua payload THAT (05/09/2026):
// - field "content" (mo ta): before/after la CHUOI JSON dang Quill Delta {"ops":[{"insert":"..."}]}
//   KHONG phai text thuong -> can parse rieng.
// - field "custom_field": co san object h.custom_field = {id, name, type,...} - map theo TEN
//   (giong fieldNameMap ben Full Reconcile), KHONG map theo h.field (luon la chuoi "custom_field").
// - taskCommentPosted/Updated: history_items[0].comment DA CO SAN toan bo noi dung comment moi
//   (bao gom mang comment[].attributes.link/bookmark.url va text_content) -> KHONG CAN goi lai API
//   lay comment nua (Code node tren instance nay khong ho tro httpRequestWithAuthentication).
const body = $json;
const event = body.event;
const taskId = body.task_id;
const historyItems = body.history_items || [];
const isCommentEvent = event === 'taskCommentPosted' || event === 'taskCommentUpdated';

const CUSTOM_FIELD_TO_COLUMN = {
  "B1 Datum": "b1_datum", "DOB": "dob", "Mã HĐ": "ma_hd", "Nghề": "nghe", "SDT": "sdt",
  "email": "email", "Địa chỉ VN": "dia_chi_vn", "🌍 VFS": "vfs",
  "📆 Dự kiến thời gian đến Đức": "du_kien_den_duc", "🛫 Ngày xuất cảnh": "ngay_xuat_canh",
  "DKPV 2026": "dkpv_2026", "PVTC 2026": "pvtc_2026", "Nhà cửa / Support": "nha_cua_support",
  "Phụ trách": "phu_trach", "DKPV": "dkpv", "PVTC": "pvtc", "VFS": "vfs_khong_dau",
  "Plan bay": "planbay", "Ngày bay": "ngaybay", "Color": "color", "Link khác": "other_link",
};

function extractPlainTextFromDelta(raw) {
  try {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed && Array.isArray(parsed.ops)) {
      return parsed.ops.map(op => (typeof op.insert === 'string' ? op.insert : '')).join('').trim();
    }
  } catch (e) { }
  return typeof raw === 'string' ? raw : '';
}

function formatCustomFieldValue(h) {
  const cf = h.custom_field;
  let val = h.after;
  if (cf && cf.type === 'date' && /^\d{10,13}$/.test(String(val))) {
    const d = new Date(Number(val));
    if (!isNaN(d.getTime())) {
      const dd = String(d.getDate()).padStart(2, '0');
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      return `${dd}/${mm}/${d.getFullYear()}`;
    }
  }
  if (val && typeof val === 'object') return JSON.stringify(val);
  return val;
}

const URL_RE = /https?:\/\/[^\s)"'\]]+/g;
function classifyLink(url) {
  const u = url.toLowerCase();
  if (u.includes('onedrive.live.com') || u.includes('1drv.ms') || u.includes('sharepoint.com')) return 'onedrive';
  if (u.includes('youtube.com') || u.includes('youtu.be')) return 'youtube';
  return null;
}

let updates = [];
let commentLink = null, commentKind = null, commentAuthor = null;

if (isCommentEvent) {
  for (const h of historyItems) {
    if (h.field !== 'comment' || !h.comment) continue;
    commentAuthor = h.user?.username || 'không rõ';
    const segs = Array.isArray(h.comment.comment) ? h.comment.comment : [];
    for (const seg of segs) {
      const candidate = seg.bookmark?.url || seg.attributes?.link;
      if (candidate) {
        const k = classifyLink(candidate);
        if (k) { commentLink = candidate; commentKind = k; break; }
      }
    }
    if (!commentLink) {
      const plain = h.comment.text_content || '';
      for (const url of (plain.match(URL_RE) || [])) {
        const k = classifyLink(url);
        if (k) { commentLink = url; commentKind = k; break; }
      }
    }
  }
} else {
  for (const h of historyItems) {
    let column = null, newValue = null;
    const changedBy = h.user?.username || 'không rõ';
    let fieldLabel = h.field;

    if (h.field === 'status') {
      column = 'status';
      newValue = (h.after && typeof h.after === 'object') ? (h.after.status || h.after.name) : h.after;
    } else if (h.field === 'name') {
      column = 'name'; newValue = h.after;
    } else if (h.field === 'content') {
      column = 'description'; newValue = extractPlainTextFromDelta(h.after); fieldLabel = 'Mô tả';
    } else if (h.field === 'custom_field' && h.custom_field) {
      const cfName = h.custom_field.name;
      column = CUSTOM_FIELD_TO_COLUMN[cfName] || null;
      if (column) { newValue = formatCustomFieldValue(h); fieldLabel = cfName; }
    }

    if (!column) continue;
    updates.push({ column, newValue, changedBy, fieldLabel });
  }
}

return [{
  json: {
    taskId, event, isCommentEvent, updates,
    commentLink, commentKind, commentAuthor,
  }
}];

// Chi cho phep whitelist cot duoc update (tranh SQL injection qua ten cot dong)
const ALLOWED_COLUMNS = ["status", "name", "description", "phu_trach", "dkpv", "pvtc", "vfs", "planbay", "ngaybay", "color", "b1_datum", "dob", "ma_hd", "nghe", "sdt", "email", "dia_chi_vn", "vfs_khong_dau", "du_kien_den_duc", "ngay_xuat_canh", "dkpv_2026", "pvtc_2026", "nha_cua_support", "other_link"];
const u = $json;
if (!ALLOWED_COLUMNS.includes(u.column)) {
  return []; // bo qua field khong trong whitelist, khong lam gi
}
return [{ json: { ...u, taskId: $('Phân tích Webhook Payload').first().json.taskId } }];

const pgRow = $json;
const meta = $('Lọc cột hợp lệ').first().json;
const admin = $('Lay Admin Chat ID (F2)').first().json;

const FIELD_LABELS = {"status": "Trạng thái", "name": "Tên task", "description": "Mô tả", "phu_trach": "Phụ trách", "dkpv": "DKPV", "pvtc": "PVTC", "vfs": "VFS", "planbay": "Plan bay", "ngaybay": "Ngày bay", "color": "Color", "b1_datum": "B1 Datum", "dob": "DOB", "ma_hd": "Mã HĐ", "nghe": "Nghề", "sdt": "SDT", "email": "Email", "dia_chi_vn": "Địa chỉ VN", "vfs_khong_dau": "VFS", "du_kien_den_duc": "Dự kiến đến Đức", "ngay_xuat_canh": "Ngày xuất cảnh", "dkpv_2026": "DKPV 2026", "pvtc_2026": "PVTC 2026", "nha_cua_support": "Nhà cửa / Support", "other_link": "Link khác"};
const label = FIELD_LABELS[meta.column] || meta.column;
const now = new Date();

const text = `🔄 <b>Thông báo CẬP NHẬT Task</b>\n\n` +
  `🔧 Thay đổi:\n` +
  `📝 Trường "${label}" được cập nhật bởi ${meta.changedBy}\n` +
  `✅ Giá trị mới: ${meta.newValue ?? '—'}\n\n` +
  `📦 Thông tin:\n` +
  `🆔 ID: ${pgRow.id}\n` +
  `📌 Tên: ${pgRow.name || '—'}\n` +
  `🔗 Link: ${pgRow.url || '—'}\n` +
  `🕒 Cập nhật lúc: ${now.toLocaleString('vi-VN')} #task_updated`;

return [{ json: { chatId: admin.admin_chat_id, text } }];

const pgRow = $input.all()[0].json; // { id, name, url } tu RETURNING cua Update Postgres (comment)
const meta = $('Phân tích Webhook Payload').first().json; // { commentAuthor, commentLink, commentKind, taskId }
const admin = $('Lay Admin Chat ID (F2)').first().json;
const now = new Date();

const newValueDisplay = meta.commentLink || '(không tìm thấy link trong comment)';

const text = `🔄 <b>Thông báo CẬP NHẬT Task</b>\n\n` +
  `🔧 Thay đổi:\n` +
  `📝 Trường "comment" được cập nhật bởi ${meta.commentAuthor || 'không rõ'}\n` +
  `✅ Giá trị mới: ${newValueDisplay}\n\n` +
  `📦 Thông tin:\n` +
  `🆔 ID: ${pgRow ? pgRow.id : meta.taskId || '—'}\n` +
  `📌 Tên: ${pgRow ? (pgRow.name || '—') : '—'}\n` +
  `🔗 Link: ${pgRow ? (pgRow.url || '—') : '—'}\n` +
  `🕒 Cập nhật lúc: ${now.toLocaleString('vi-VN')} #task_updated`;

return [{ json: { chatId: admin.admin_chat_id, text } }];
